package main

import "fmt"

func main() {
	puerto := 8080
	fmt.Println(puerto) // 8080

	puerto = 8081
	fmt.Println(puerto) // 8081

	// Se calcula la derecha
	// y se guarda a la izquierda
	puerto = puerto + 1
	fmt.Println(puerto) // 8082
}

